from fontTools.fontBuilder import FontBuilder
from fontTools.pens.ttGlyphPen import TTGlyphPen
from pathlib import Path
patterns = {
'A':'01110/10001/10001/11111/10001/10001/10001','B':'11110/10001/10001/11110/10001/10001/11110','C':'01111/10000/10000/10000/10000/10000/01111','D':'11110/10001/10001/10001/10001/10001/11110','E':'11111/10000/10000/11110/10000/10000/11111','F':'11111/10000/10000/11110/10000/10000/10000','G':'01111/10000/10000/10111/10001/10001/01111','H':'10001/10001/10001/11111/10001/10001/10001','I':'11111/00100/00100/00100/00100/00100/11111','J':'00111/00010/00010/00010/10010/10010/01100','K':'10001/10010/10100/11000/10100/10010/10001','L':'10000/10000/10000/10000/10000/10000/11111','M':'10001/11011/10101/10101/10001/10001/10001','N':'10001/11001/10101/10011/10001/10001/10001','O':'01110/10001/10001/10001/10001/10001/01110','P':'11110/10001/10001/11110/10000/10000/10000','Q':'01110/10001/10001/10001/10101/10010/01101','R':'11110/10001/10001/11110/10100/10010/10001','S':'01111/10000/10000/01110/00001/00001/11110','T':'11111/00100/00100/00100/00100/00100/00100','U':'10001/10001/10001/10001/10001/10001/01110','V':'10001/10001/10001/10001/10001/01010/00100','W':'10001/10001/10001/10101/10101/11011/10001','X':'10001/10001/01010/00100/01010/10001/10001','Y':'10001/10001/01010/00100/00100/00100/00100','Z':'11111/00001/00010/00100/01000/10000/11111',
'0':'01110/10001/10011/10101/11001/10001/01110','1':'00100/01100/00100/00100/00100/00100/01110','2':'01110/10001/00001/00010/00100/01000/11111','3':'11110/00001/00001/01110/00001/00001/11110','4':'00010/00110/01010/10010/11111/00010/00010','5':'11111/10000/10000/11110/00001/00001/11110','6':'01110/10000/10000/11110/10001/10001/01110','7':'11111/00001/00010/00100/01000/01000/01000','8':'01110/10001/10001/01110/10001/10001/01110','9':'01110/10001/10001/01111/00001/00001/01110',
'.':'00000/00000/00000/00000/00000/00110/00110',',':'00000/00000/00000/00000/00110/00110/00100',':':'00000/00100/00100/00000/00100/00100/00000','!':'00100/00100/00100/00100/00100/00000/00100','?':'01110/10001/00001/00010/00100/00000/00100','-':'00000/00000/00000/11111/00000/00000/00000','+':'00000/00100/00100/11111/00100/00100/00000','/':'00001/00010/00010/00100/01000/01000/10000',"'":'00100/00100/00000/00000/00000/00000/00000','&':'01100/10010/10100/01000/10101/10010/01101','=':'00000/00000/11111/00000/11111/00000/00000','(':'00010/00100/01000/01000/01000/00100/00010',')':'01000/00100/00010/00010/00010/00100/01000'
}
patterns[' '] = '00000/' * 6 + '00000'
fb=FontBuilder(800,isTTF=True)
order=['.notdef']+['g'+str(ord(c)) for c in patterns]
fb.setupGlyphOrder(order)
cmap={ord(c):'g'+str(ord(c)) for c in patterns}
cmap.update({ord(c.lower()):'g'+str(ord(c)) for c in patterns if c.isalpha()})
fb.setupCharacterMap(cmap)
glyphs={}; metrics={}
for c,pattern in patterns.items():
    pen=TTGlyphPen(None)
    for row,line in enumerate(pattern.split('/')):
        for col,pixel in enumerate(line):
            if pixel=='1':
                x=col*100;y=(6-row)*100
                pen.moveTo((x,y));pen.lineTo((x,y+100));pen.lineTo((x+100,y+100));pen.lineTo((x+100,y));pen.closePath()
    name=cmap[ord(c)];glyphs[name]=pen.glyph();metrics[name]=(600 if c!=' ' else 350,0)
glyphs['.notdef']=TTGlyphPen(None).glyph();metrics['.notdef']=(600,0)
fb.setupGlyf(glyphs);fb.setupHorizontalMetrics(metrics);fb.setupHorizontalHeader(ascent=800,descent=-100)
fb.setupNameTable({'familyName':'Garden Pixel','styleName':'Regular','uniqueFontIdentifier':'BirthdayFeudGardenPixel','fullName':'Garden Pixel Regular','psName':'GardenPixel-Regular','version':'Version 1.0'})
fb.setupOS2(sTypoAscender=800,sTypoDescender=-100,usWinAscent=800,usWinDescent=100,sxHeight=700,sCapHeight=700)
fb.setupPost();fb.setupMaxp();fb.save('public/assets/fonts/garden-pixel.ttf')
print('Built Garden Pixel font')
